        log.output(".{s},", .{"VK_SAMPLE_COUNT_2_BIT"});
    if (@field(value.sampleCounts, "VK_SAMPLE_COUNT_4_BIT"))
        log.output(".{s},", .{"VK_SAMPLE_COUNT_4_BIT"});
    if (@field(value.sampleCounts, "VK_SAMPLE_COUNT_8_BIT"))
