    for (0..offset + 1) |_| log.output("    ", .{});
    log.output("sType: VkStructureType = {t},\n", .{value.sType});
    for (0..offset + 1) |_| log.output("    ", .{});
    log.output("accelerationStructureCount: u32 = {d},\n", .{value.accelerationStructureCount});
